import Phaser from 'phaser';
import './style.css';

const W = 960, H = 540;

function ensureTrueMark(scene: Phaser.Scene) {
  if (scene.textures.exists('true-mark')) return;
  const mark = scene.add.graphics();
  mark.lineStyle(20, 0xffffff, 1).strokeEllipse(188, 137, 300, 172);
  mark.lineStyle(20, 0xffffff, 1).lineBetween(30, 112, 346, 112);
  mark.lineStyle(20, 0xffffff, 1).lineBetween(188, 112, 188, 248);
  mark.generateTexture('true-mark', 377, 270); mark.destroy();
}

function addTrueMarkPickup(scene: Phaser.Scene, x: number, y: number, width: number, depth: number) {
  const height = width * 270 / 377;
  const glow = scene.add.image(x, y, 'true-mark').setDepth(depth - .1).setDisplaySize(width * 1.45, height * 1.45).setTint(0x9b62ff).setAlpha(.26);
  const item = scene.physics.add.image(x, y, 'true-mark').setDepth(depth).setDisplaySize(width, height);
  item.setData('logoGlow', glow);
  scene.tweens.add({ targets: [item, glow], y: y - 9, duration: 900, yoyo: true, repeat: -1, ease: 'Sine.easeInOut' });
  scene.tweens.add({ targets: glow, alpha: { from: .2, to: .38 }, displayWidth: width * 1.62, displayHeight: height * 1.62, duration: 850, yoyo: true, repeat: -1, ease: 'Sine.easeInOut' });
  scene.tweens.add({ targets: item, displayWidth: width * .95, displayHeight: height * 1.05, duration: 750, yoyo: true, repeat: -1, ease: 'Sine.easeInOut' });
  return item;
}

function removeTrueMarkPickup(item: Phaser.Physics.Arcade.Image) {
  (item.getData('logoGlow') as Phaser.GameObjects.Image | undefined)?.destroy();
  item.destroy();
}

function addTrueMarkHud(scene: Phaser.Scene, x: number, y: number, size = 25) {
  scene.add.image(x, y, 'true-mark').setScrollFactor(0).setDepth(21).setDisplaySize(size * 1.45, size * 270 / 377 * 1.45).setTint(0x9b62ff).setAlpha(.28);
  scene.add.image(x, y, 'true-mark').setScrollFactor(0).setDepth(22).setDisplaySize(size, size * 270 / 377);
}

function showTrueMarkReward(scene: Phaser.Scene, x: number, y: number, depth = 14) {
  const iconX = x - 54, iconY = y - 13;
  const glow = scene.add.image(iconX, iconY, 'true-mark').setDepth(depth - 1).setDisplaySize(29, 21).setTint(0x9b62ff).setAlpha(.34);
  const mark = scene.add.image(iconX, iconY, 'true-mark').setDepth(depth).setDisplaySize(21, 15);
  scene.tweens.add({ targets: [mark, glow], y: y - 45, alpha: 0, duration: 650, onComplete: () => { mark.destroy(); glow.destroy(); } });
}

