  private nextDialog(){if(this.remaining.length){this.dialogText.setText(this.remaining.shift()!);return;}this.dialogue=false;this.dialogBox.setVisible(false);this.physics.world.resume();}
  private discoverGate(index:number){if(this.discovered.has(index))return;const g=this.gates[index];this.discovered.add(index);this.updateHud();this.gateCores[index].setFillStyle(g.color,.78).setStrokeStyle(3,0xffffff,.95);this.tweens.add({targets:this.gateCores[index],scaleX:1.2,scaleY:1.2,duration:280,yoyo:true});const burst=this.add.circle(g.x,387,11,g.color,.8).setDepth(9);this.tweens.add({targets:burst,scale:3.2,alpha:0,duration:450,onComplete:()=>burst.destroy()});this.showDialog([`${g.name}: ${g.copy}`,'These are TRUE trading-platform features. $TRUE token utility has a separate rollout; check TRUE Foundation for current status.']);}
