  update(){if(this.dialogue){if(Phaser.Input.Keyboard.JustDown(this.keys.E)||Phaser.Input.Keyboard.JustDown(this.cursors.space)||this.touch.interact){this.touch.interact=false;this.dialogue=false;this.dialogBox.setVisible(false);this.physics.world.resume();}return;}if(this.paused||this.finished)return;const left=this.cursors.left.isDown||this.keys.A.isDown||this.touch.left,right=this.cursors.right.isDown||this.keys.D.isDown||this.touch.right,body=this.player.body as Phaser.Physics.Arcade.Body,grounded=body.blocked.down||body.touching.down;this.player.setVelocityX(left?-225:right?225:0);if(grounded&&(Phaser.Input.Keyboard.JustDown(this.cursors.up)||Phaser.Input.Keyboard.JustDown(this.cursors.space)||Phaser.Input.Keyboard.JustDown(this.keys.SPACE)||this.touch.jump))this.player.setVelocityY(-580);this.touch.jump=false;this.player.play(Math.abs(body.velocity.x)>5?'hero-run':grounded?'hero-idle':body.velocity.y<0?'hero-jump':'hero-fall',true);this.player.setFlipX(left);if(this.player.y>720){this.player.setPosition(this.checkpoint,389).setVelocity(0,0);this.showDialog(['The clouds softened your landing. Continue from the last checkpoint.']);return;}if(Phaser.Math.Distance.Between(this.player.x,this.player.y,this.portalZone.x,this.portalZone.y)<75){this.finish();return;}if(Phaser.Math.Distance.Between(this.player.x,this.player.y,this.npc.x,this.npc.y)<125){this.prompt.setText('E  TALK · TGE GUIDE').setPosition(this.npc.x,this.npc.y-68).setVisible(true);if(Phaser.Input.Keyboard.JustDown(this.keys.E)||this.touch.interact){this.touch.interact=false;this.showDialog(['We are celebrating the $TRUE listing on TRUE DEX, on Solana.','The announced listing is October 15, 2026 at 18:00 CET. Check TRUE Foundation for current details.']);}}else{this.prompt.setVisible(false);this.touch.interact=false;}}
